parameters.text:
=New enquiry for {{ $json.businessName }}.

Name: {{ $json.patientName }}
How soon: {{ $json.howSoon }}
Insurance: {{ $json.insurance }}
Their message: """{{ $json.problem }}"""

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "urgency": {
      "type": "string",
      "enum": [
        "emergency",
        "soon",
        "routine"
      ]
    },
    "treatment": {
      "type": "string",
      "description": "Most likely service from the price list, or General enquiry"
    },
    "score": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "description": "Lead value and readiness, 10 = book today, high value"
    },
    "estimatedValue": {
      "type": "number",
      "description": "Likely first-visit value in dollars, from the price list"
    },
    "summary": {
      "type": "string",
      "description": "One line for the front desk"
    },
    "reasoning": {
      "type": "string",
      "description": "Why this urgency and score"
    },
    "replySubject": {
      "type": "string"
    },
    "replyHtml": {
      "type": "string",
      "description": "Email body as simple HTML paragraphs"
    }
  },
  "required": [
    "urgency",
    "treatment",
    "score",
    "estimatedValue",
    "summary",
    "reasoning",
    "replySubject",
    "replyHtml"
  ]
}

additionalFields.description:
=Urgency: {{ $('AI rates the enquiry and drafts a reply').item.json.output.urgency }} | Score: {{ $('AI rates the enquiry and drafts a reply').item.json.output.score }}/10
{{ $('AI rates the enquiry and drafts a reply').item.json.output.summary }}
Why: {{ $('AI rates the enquiry and drafts a reply').item.json.output.reasoning }}

